<?php
namespace App\Services\Payments;
use App\Models\{Venue,Booking,BookingPayment,GatewayAccount,CheckoutAttempt};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class PaymentService {
 public function start(Booking $booking,string $provider,string $purpose,GatewayDriver $driver,bool $accepted=false):CheckoutAttempt{
 abort_unless(in_array($provider,['paypal','mercadopago','oxxo'])&&in_array($purpose,['deposit','balance']),422);
 if(!app()->environment(['testing','local']))abort_unless(str_starts_with(config('portal.customer_url'),'https://'),422,'Configura CUSTOMER_URL con un dominio HTTPS antes de activar el checkout.');
 $created=false;
 $a=DB::transaction(function()use($booking,$provider,$purpose,&$created,$accepted){$created=false;Venue::whereKey($booking->venue_id)->lockForUpdate()->firstOrFail();$b=Booking::whereKey($booking->id)->lockForUpdate()->firstOrFail();abort_unless(in_array($b->status,['hold','confirmed']),422,'La reserva no admite pagos.');if($b->status==='hold')abort_unless($b->expires_at?->isFuture(),422,'El apartado venció. Elige la fecha nuevamente.');
 $paid=(int)$b->payments()->sum('amount');$amount=$purpose==='deposit'?max(0,$b->deposit-$paid):max(0,$b->total-$paid);abort_unless($amount>0,422,'No hay un importe pendiente para esa opción.');
 $active=CheckoutAttempt::where('booking_id',$b->id)->whereIn('status',['creating','pending','unknown'])->where('expires_at','>',now())->lockForUpdate()->first();
 if($active){
  if($active->provider===$provider&&$active->amount===$amount){if($accepted&&!$active->policy_acceptance)$active->update(['policy_acceptance'=>\App\Services\ReservationPolicy::acceptance()]);return $active;}
  // Only our server can capture these PayPal orders. Retire the previous order
  // under the same venue/booking locks used when claiming a capture.
  $replaceable=$active->provider==='paypal'&&$provider==='paypal'&&$active->status==='pending'&&!$active->paid_transaction_id&&empty($active->checkout['capture_started_at']);
  abort_unless($replaceable,422,'Hay un pago en proceso. Consulta su estado antes de cambiar el importe o el método.');
  $active->update(['status'=>'superseded','expires_at'=>now()]);
 }
 $g=GatewayAccount::where('venue_id',$b->venue_id)->where('provider',$provider)->where('current',true)->where('enabled',true)->firstOrFail();app(GatewayCredentials::class)->require($g,true);
 $window=app(CheckoutWindow::class)->assess($b,$provider);abort_unless($window['available'],422,$window['unavailable_reason']);$expires=\Carbon\CarbonImmutable::parse($window['expires_at']);if($b->status==='hold')$b->update(['expires_at'=>$expires]);$created=true;return CheckoutAttempt::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'gateway_account_id'=>$g->id,'provider'=>$provider,'purpose'=>$purpose,'amount'=>$amount,'currency'=>'MXN','status'=>'creating','expires_at'=>$expires,'policy_acceptance'=>$accepted?\App\Services\ReservationPolicy::acceptance():null]);},3);
 if(!$created)return $a;
 try{$data=$driver->create($a);$a->update(['external_id'=>$data['external_id'],'checkout'=>$data['checkout'],'status'=>'pending']);}catch(\Throwable $e){$failure=app(PaymentFailure::class);$failure->record($a,$e,'create');$rejected=$failure->rejected($e);$a->refresh();if($a->paid_transaction_id)return $a;if(!$a->paid_transaction_id)$a->update(['status'=>$rejected?'failed':'unknown','review_reason'=>$rejected?'No se pudo iniciar el pago.':'Estamos comprobando el estado del pago.']);if(!$rejected)return $a->fresh();throw new \Symfony\Component\HttpKernel\Exception\HttpException(422,'No pudimos abrir el pago en este momento. Tu reservación se conserva; intenta con otro método o contacta al establecimiento.');}return $a->fresh();
 }
 public function authorizeCapture(CheckoutAttempt $a,bool $claim=false):void{DB::transaction(function()use($a,$claim){$b=$a->booking;Venue::whereKey($b->venue_id)->lockForUpdate()->firstOrFail();$b=Booking::whereKey($b->id)->lockForUpdate()->firstOrFail();$a=CheckoutAttempt::whereKey($a->id)->lockForUpdate()->firstOrFail();abort_unless(in_array($a->status,['pending','unknown'],true),422,'Este intento ya no está disponible. Elige el importe desde Mis reservas.');if($claim){abort_if(!empty($a->checkout['capture_started_at']),422,'Este pago ya se está comprobando. Su estado se actualizará automáticamente.');$a->update(['checkout'=>array_merge($a->checkout??[],['capture_started_at'=>now()->toIso8601String()])]);}abort_unless(in_array($b->status,['hold','confirmed'])&&($b->status==='confirmed'||$b->starts_at->isFuture()),422,'La reserva ya no admite un cargo nuevo.');abort_unless($a->expires_at->isFuture(),422,'El intento de pago venció. Consulta su estado antes de iniciar otro.');$conflict=$b->venue->bookings()->blocking()->where('id','!=',$b->id)->where('blocked_from','<',$b->blocked_until)->where('blocked_until','>',$b->blocked_from)->exists();abort_if($conflict,422,'El horario ya fue ocupado. No se realizará un cargo nuevo.');abort_unless($b->total-(int)$b->payments()->sum('amount')>=$a->amount,422,'El saldo cambió. No se realizará un cargo nuevo.');if($b->status==='hold'){$holdUntil=now()->addMinutes(15);if($b->starts_at->lt($holdUntil))$holdUntil=$b->starts_at;$b->update(['expires_at'=>$holdUntil]);}},3);}
 public function settle(GatewayAccount $g,array $data):?CheckoutAttempt{
 $a=CheckoutAttempt::where('id',$data['reference'])->where('gateway_account_id',$g->id)->first();if(!$a)return null;
 abort_unless($data['amount']===$a->amount&&$data['currency']==='MXN',422,'El importe o moneda no coincide.');if($g->provider!=='mercadopago')abort_unless($data['external_id']===$a->external_id||!$a->external_id,422,'La orden del proveedor no coincide.');if(in_array($g->provider,['paypal','mercadopago']))abort_unless((string)$data['merchant']===(string)(app(GatewayCredentials::class)->require($g)['merchant_id']??''),422,'La cuenta receptora no coincide.');if(!$data['paid'])return $a;
 abort_unless(filled($data['transaction']),422,'Pago sin identificador de transacción.');
 $result=DB::transaction(function()use($a,$data,$g){$b=Booking::whereKey($a->booking_id)->firstOrFail();Venue::whereKey($b->venue_id)->lockForUpdate()->firstOrFail();$b=Booking::whereKey($b->id)->lockForUpdate()->firstOrFail();$a=CheckoutAttempt::whereKey($a->id)->lockForUpdate()->firstOrFail();$tx=$g->provider.':'.$g->id.':'.$data['transaction'];$exists=BookingPayment::where('provider_transaction_id',$tx)->exists();if(!$exists){$already=(int)$b->payments()->sum('amount');$conflict=$b->venue->bookings()->blocking()->where('id','!=',$b->id)->where('blocked_from','<',$b->blocked_until)->where('blocked_until','>',$b->blocked_from)->exists();$attention=null;if(!in_array($b->status,['hold','confirmed']))$attention='Pago recibido para una reserva cancelada o no activa; requiere revisión.';elseif($b->status==='hold'&&$b->starts_at->isPast())$attention='Pago recibido después del inicio del evento; requiere revisión.';elseif($conflict)$attention='Pago recibido después de que el horario fuera ocupado; requiere alternativa o devolución.';elseif($already+$a->amount>$b->total)$attention='Se recibió más dinero que el total; revisa y tramita la devolución del excedente.';
 $payment=BookingPayment::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'recorded_by'=>$b->user_id,'amount'=>$a->amount,'method'=>$g->provider,'reference'=>$data['transaction'],'idempotency_key'=>(string)Str::uuid(),'provider_transaction_id'=>$tx]);if($attention){$b->update(['payment_attention'=>$attention]);$a->status='review';$a->review_reason=$attention;}else{$b->update(['status'=>'confirmed','expires_at'=>null]);$a->status='paid';if(($data['refunded']??0)===0&&$b->starts_at->isFuture())app(\App\Services\Email\PaymentEmails::class)->enqueue($b,$payment);}}
 $a->paid_transaction_id=$data['transaction'];if(!$a->external_id)$a->external_id=$data['external_id'];$a->save();return $a;},3);
 if(($data['refunded']??0)>0)$this->refundCumulative($result,(int)$data['refunded']);return $result->fresh();
 }
 public function refundCumulative(CheckoutAttempt $a,int $amount):void{$prefix=$a->provider.':'.$a->gateway_account_id.':'.$a->paid_transaction_id.':refund:';DB::transaction(function()use($a,$amount,$prefix){$b=$a->booking;Venue::whereKey($b->venue_id)->lockForUpdate()->firstOrFail();$refunded=-(int)$b->payments()->where('provider_transaction_id','like',$prefix.'%')->sum('amount');$delta=$amount-$refunded;if($delta<=0)return;abort_if($amount>$a->amount,422);BookingPayment::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'recorded_by'=>$b->user_id,'amount'=>-$delta,'method'=>$a->provider,'reference'=>'Devolución verificada','idempotency_key'=>(string)Str::uuid(),'provider_transaction_id'=>$prefix.$amount]);$b->update(['payment_attention'=>'El proveedor notificó una devolución o reversión. Revisa el saldo y el estado del evento.']);$a->update(['status'=>$amount===$a->amount?'refunded':'partially_refunded']);});}
 public function refundPayPal(GatewayAccount $g,array $refund):void{$a=CheckoutAttempt::where('gateway_account_id',$g->id)->where('paid_transaction_id',$refund['capture'])->first();if(!$a)return;abort_unless($refund['currency']==='MXN'&&$refund['amount']<=$a->amount,422);DB::transaction(function()use($a,$g,$refund){$b=$a->booking;Venue::whereKey($b->venue_id)->lockForUpdate()->firstOrFail();$tx='paypal:'.$g->id.':'.$refund['capture'].':refund:'.$refund['refund_id'];if(BookingPayment::where('provider_transaction_id',$tx)->exists())return;$already=-(int)$b->payments()->where('provider_transaction_id','like','paypal:'.$g->id.':'.$refund['capture'].':refund:%')->sum('amount');$effective=min($refund['amount'],$a->amount-$already);if($effective<=0)return;BookingPayment::create(['id'=>(string)Str::uuid(),'booking_id'=>$b->id,'recorded_by'=>$b->user_id,'amount'=>-$effective,'method'=>'paypal','reference'=>$refund['refund_id'],'idempotency_key'=>(string)Str::uuid(),'provider_transaction_id'=>$tx]);$b->update(['payment_attention'=>'PayPal confirmó una devolución. Revisa el saldo y el estado del evento.']);$a->update(['status'=>$already+$effective===$a->amount?'refunded':'partially_refunded']);});}
}
